column99:
16/Jan/10 12:37 PM;557058:3564dbfd-03c5-46c9-9e5c-3219aea344c7;My webdev is behaving strangely and I can't upload a theme.

content.css:

/*MEYERS RESET.***********************************************do not edit */
html, body, div, span, applet, object, iframe, h1, h2, h3, h4, h5, h6, 
p, blockquote, pre, a, abbr, acronym, address, big, cite, code, del, dfn, 
em, img, ins, kbd, q, s, samp, small, strike, strong, sub, sup, tt, var, 
dl, dt, dd, ol, ul, li, fieldset, form, label, legend, 
table, caption, tbody, tfoot, thead, tr, th, td	
{ border: 0; outline: 0; font-weight: inherit; font-style: inherit; font-size: 100%;
font-family: inherit; vertical-align: baseline; list-style: none; margin: 0; padding:
0; }
/************************************************end of uneditable rules */

/* Fertigo by Jos Buivenga (exljbris) -> www.exljbris.nl */
@font-face {
	  font-family: "Fertigo";
	  src: url(Fertigo.otf)
	  	  format("opentype");
}

body					{ background: #fffef9; color: #222; font: 100%/1.125 'Lucida Grande',
Verdana, Helvetica, Arial, sans-serif; }

a, a:link				{ color: #111; }
a:hover					{ color: #999; }
a:active, a:focus 		{ outline:1px dotted;}
a:visited				{ color: #777; }
a img					{ border: 0; }

/*EM SCALE */
p						{ font-size: 0.875em; line-height: 1.286; margin: 0.5em 0; }
li, dd					{ font-size: 0.875em; line-height: 1.286; margin: 0.5em 0; } 
dl dd dl dd p,  dl dd dl dd,  dd dl dd p,  dd dl dd dl dd p	{ font-size:1.142857em;
}
li li,  li li li,  li p,  li dd,  li dd p,  dd p,  dd li,  dd li p, dd dl dd dl dd
p,
 dd dl dd dl dd ul li,  dd dl dd dl dd ul li p,  dl dd dl dd,  dl dd dl dd p,  dl dd
dl dt,  li li dl dt	
						{ font-size:1em; }

h1, h2, h3, h4, h5, h6	{ font-family: Fertigo, Cambria, Constantia, Palatino,
Georgia, sans-serif; font-weight: 400;}
h1						{ font-size: 2.25em; line-height: 1; margin: 0.5em 0; font-family:Cambria,
Constantia, Palatino, Georgia, serif; text-align:center; }
h2						{ font-size: 1.5em; line-height: 1;  color:#333; font-variant:normal;
text-align:left; text-transform:none; margin:1.5em 0;}
h3						{ font-size: 1.125em; line-height: 1; margin: 1em 0; background:#333;
color:#fffef9; font-weight:100; padding: 0.125em; border-bottom:0.25em double #fffef9;}
h4						{ line-height: 1.125; margin:1.138889em 0; font-variant:small-caps;
font-size:1.25em;}
h5						{ line-height: 1.1286; margin:0.643em 0; font-weight:600; font-size: 1em;}
h6						{ line-height: 1.5; margin: 1.5em 0; font-size: 0.975em; border-bottom:1px
solid}
h3 a, h3 a:link, h3 a:visited { color:#fffef9; border-bottom:0; text-decoration: none;
}

hr						{ width:33%; margin:0.875em auto 1.2525em auto; border:1px solid; }

blockquote, pre			{ font: 100 1em/1.125 'Lucida Grande', Verdana, Helvetica, Tahoma,
Arial, sans-serif;  margin: 1.5em; }
blockquote				{ font-size:1em; margin:auto auto auto 1.5em; padding:0.75em;
border-left:2px solid #999; }
blockquote blockquote	{ padding:0.25em; border:0; }
kbd, tt, code, var		{ font: normal 0.75em consolas, courier, monospace; margin: auto;
padding: 0.25em; }
p code					{ font-size: 0.98em;}
pre 					{ white-space: pre; }
strong, b, .important	{ font-weight: bolder; }
em, cite, i				{ font-style: oblique; }
cite em, em cite, cite i, i cite, i em, em i, em em, i i, cite cite	
						{ font-style: normal; }
em cite, i cite			{ text-decoration: underline; }
dfn, abbr, acronym		{ font-variant: small-caps; cursor: help; }
del, strike 			{ text-decoration:line-through;}
ins, u 					{ text-decoration: underline;}
big 					{ font-size: larger;}
small, sub, sup 		{ font-size: smaller;}
small small small small { font-size: 100%;}
sub 					{ vertical-align: sub;}
sup 					{ vertical-align:super;}

table					{ margin:auto; padding: 0.375em; width:99%;}
caption, th, td			{ text-align: left; }
th, thead td 			{ color:222; font-weight: bolder; padding: 0.25em;}
tfoot 					{ margin: 0.875em auto;}
td th					{ padding-right: 3em; }
td						{ padding:0.375em;}

dl		{ font-size:1em; margin:1.5em 0; border: 0; }
dl dl	{ width:90%; margin:auto;}
dt		{ font-weight:bold; text-indent:0;}
dd		{ line-height:1.5; font-size:0.875em; margin:1.25em auto 1.25em 3em; }
dd p	{ text-indent:0; margin:0; padding:0; }
ul		{ margin:1.125em auto; padding:0 1em; }
li		{ list-style-type:disc; margin:0.75em 0 0.75em 1.75em;}
ol		{ margin:0.75em auto; padding:0 1.5em; }
ol li	{ list-style-type:decimal; margin:0.75em 0 0.75em 1.75em ;}
ol li ol li	{ list-style-type: lower-alpha;}
ol li ol li ol li	{ list-style-type: lower-roman;}
li		{ font-weight:normal; }

/*expected behaviours, exceptioning*/
center { font-size: 0.875em; line-height: 1.286; margin: 0.643em 0; } 
center p 	{ font-size: 1em; }

.mceVisualAid {
	border: 1px dashed #BBBBBB;
}

/* MSIE specific */

* html body {
	scrollbar-3dlight-color: #F0F0EE;
	scrollbar-arrow-color: #676662;
	scrollbar-base-color: #F0F0EE;
	scrollbar-darkshadow-color: #DDDDDD;
	scrollbar-face-color: #E0E0DD;
	scrollbar-highlight-color: #F0F0EE;
	scrollbar-shadow-color: #F0F0EE;
	scrollbar-track-color: #F5F5F5;	
}
